// Общие шаги для нескольких техников на одной работе (#80550f). Admin, компания «test».
// Настройка «Allow Multiple Techs» (Account Settings → Toggle Settings) меняется только через setMultiTech и
// ОБЯЗАТЕЛЬНО возвращается в исходное значение (afterAll в спеке). Техники — только QA-Tech Alpha/Beta/Gamma
// (вымышленные номера, без согласия на SMS). Никогда не Sofia Marin / Kirill / QA-F5 tech.
import { Browser, BrowserContext, expect, Locator, Page, TestInfo } from '@playwright/test';
import { ADMIN_STATE, L, Lang, TECH, prepare } from '../dispatch-sms/dispatch-helpers';

export { ADMIN_STATE, L, prepare };
export type { Lang };

export const TECHS = [
  TECH.alpha,
  TECH.beta,
  { name: 'QA-Tech Gamma', phone: '+13055550183' },
] as const;

export const MULTI = {
  setting: /Allow Multiple Techs/i,
  hint: /^The first technician is the lead/,
} as const;

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** Отдельное окно admin (язык EN, компания «test») — для настройки в beforeAll/afterAll. */
export async function adminContext(browser: Browser, testInfo: TestInfo): Promise<{ context: BrowserContext; page: Page }> {
  const use = testInfo.project.use;
  const context = await browser.newContext({ baseURL: use.baseURL, viewport: use.viewport ?? { width: 1440, height: 900 }, storageState: ADMIN_STATE });
  const page = await context.newPage();
  await prepare(page, 'en');
  return { context, page };
}

/**
 * Переключатель «Allow Multiple Techs».
 * // не проверено на сайте при записи (сессия admin истекла): роль switch/checkbox и есть ли вкладка «Toggle Settings».
 */
export function multiTechSwitch(page: Page): Locator {
  const row = page.locator('div').filter({ hasText: MULTI.setting }).filter({ has: page.getByRole('switch').or(page.getByRole('checkbox')) }).last();
  return page.getByRole('switch', { name: MULTI.setting })
    .or(page.getByRole('checkbox', { name: MULTI.setting }))
    .or(row.getByRole('switch'))
    .or(row.getByRole('checkbox'))
    .first();
}

async function isOn(sw: Locator): Promise<boolean> {
  const checked = await sw.getAttribute('aria-checked');
  if (checked !== null) return checked === 'true';
  const state = await sw.getAttribute('data-state');
  if (state !== null) return state === 'checked';
  return sw.isChecked();
}

/** /AccountSettings → (вкладка Toggle Settings, если есть) → переключатель видим. */
export async function openMultiTechSetting(page: Page): Promise<Locator> {
  await page.goto('/AccountSettings');
  await expect(page.getByText(/Toggle Settings|Allow Multiple Techs/i).first()).toBeVisible({ timeout: 30_000 });
  const tab = page.getByRole('tab', { name: /Toggle Settings/i });
  if (await tab.count()) await tab.first().click();
  const sw = multiTechSwitch(page);
  await expect(sw).toBeVisible();
  return sw;
}

export async function readMultiTech(page: Page): Promise<boolean> {
  return isOn(await openMultiTechSetting(page));
}

/** Включить/выключить «Allow Multiple Techs» и убедиться после перезагрузки, что сохранено. */
export async function setMultiTech(page: Page, on: boolean) {
  let sw = await openMultiTechSetting(page);
  if ((await isOn(sw)) !== on) {
    await sw.click();
    // Если настройки сохраняются кнопкой — нажать её (иначе переключатель сохраняется сразу).
    const save = page.getByRole('button', { name: /^Save( Changes| Settings)?$/i });
    if ((await save.count()) && (await save.first().isEnabled())) await save.first().click();
    await expect.poll(() => isOn(sw)).toBe(on);
  }
  sw = await openMultiTechSetting(page);
  await expect.poll(() => isOn(sw), { message: `«Allow Multiple Techs» = ${on ? 'ON' : 'OFF'} после перезагрузки` }).toBe(on);
}

/** Поле Assign Technician в панели вкладки (Job Info или Dispatch). */
export function techCombo(panel: Locator, lang: Lang): Locator {
  return panel.getByRole('combobox', { name: L[lang].assign });
}

/** Выбрать техника в открытом списке (список открывается, если закрыт). */
export async function pickTech(page: Page, combo: Locator, name: string) {
  const option = page.getByRole('option', { name: new RegExp(`^${esc(name)}\\b`) });
  if (!(await option.isVisible())) await combo.click();
  await option.click();
  if (await page.getByRole('listbox').isVisible()) await page.keyboard.press('Escape');
}

/** Тег выбранного техника (в режиме нескольких техников у тега есть кнопка Remove). */
export function techTag(area: Locator, name: string): Locator {
  return area.locator('span, div, li')
    .filter({ hasText: new RegExp(`^\\s*${esc(name)}`) })
    .filter({ has: area.page().getByRole('button', { name: /remove/i }) })
    .last();
}

export const allTechTags = (area: Locator) =>
  area.locator('span, div, li').filter({ has: area.page().getByRole('button', { name: /remove/i }) }).filter({ hasText: /^\s*QA-Tech / });

export const leadBadge = (tag: Locator) => tag.getByText(/^lead$/i);
export const removeButton = (tag: Locator) => tag.getByRole('button', { name: /remove/i });
export const makeLeadButton = (tag: Locator) => tag.getByRole('button', { name: /make lead/i });

/** Ровно этот техник — LEAD, остальные из списка — без LEAD и с «Make lead». */
export async function expectLead(area: Locator, lead: string, others: string[]) {
  await expect(leadBadge(techTag(area, lead)), `${lead} — LEAD`).toBeVisible();
  for (const name of others) {
    await expect(techTag(area, name), `тег ${name}`).toBeVisible();
    await expect(leadBadge(techTag(area, name)), `${name} — не LEAD`).toHaveCount(0);
    await expect(makeLeadButton(techTag(area, name)), `${name} — «Make lead»`).toBeVisible();
  }
}
